// Writes simple text-layer PO PDFs (same layout as scripts/make_samples.py template_one).
const fs = require("fs");
const path = require("path");
const OUT = process.argv[2];

const W = [278,278,355,556,556,889,667,191,333,333,389,584,278,333,278,278,556,556,556,556,556,556,556,556,556,556,278,278,584,584,584,556,1015,667,667,722,722,667,611,778,722,278,500,667,556,833,722,778,667,778,722,667,611,722,667,944,667,667,611,278,278,278,469,556,333,556,556,500,556,556,278,556,556,222,222,500,222,833,556,556,556,556,333,500,278,556,500,722,500,500,500,334,260,334,584];
const width = (s, size) => [...s].reduce((a, ch) => a + (W[ch.charCodeAt(0) - 32] || 556), 0) * size / 1000;
const esc = (s) => s.replace(/[\\()]/g, (m) => "\\" + m);

function makePdf(file, po) {
  const ops = [];
  const text = (x, y, s, size = 10, bold = false) => ops.push(`BT /${bold ? "F2" : "F1"} ${size} Tf ${x.toFixed(2)} ${y.toFixed(2)} Td (${esc(s)}) Tj ET`);
  const right = (x, y, s, size = 10, bold = false) => text(x - width(s, size), y, s, size, bold);
  const centre = (y, s, size, bold) => text(297.64 - width(s, size) / 2, y, s, size, bold);
  const line = (y) => ops.push(`40 ${y} m 555.28 ${y} l S`);
  const money = "Rs. ";
  let y = 841.89 - 60;
  centre(y, "PEP BRANDS", 16, true);
  centre(y - 18, "PURCHASE ORDER", 12, true);
  y -= 40; line(y); y -= 18;
  text(45, y, `PO Number : ${po.number}`);
  text(340, y, `PO Date : ${po.date}`);
  y -= 16; text(45, y, `Vendor    : ${po.vendor}`);
  y -= 14; text(101, y, po.address);
  y -= 12; line(y); y -= 16;
  text(45, y, "SKU", 10, true); text(110, y, "Description", 10, true); text(300, y, "Qty", 10, true);
  right(440, y, "Unit Price", 10, true); right(545, y, "Amount", 10, true);
  for (const [sku, desc, qty, price, amount] of po.items) {
    y -= 16;
    text(45, y, sku); text(110, y, desc); right(330, y, String(qty));
    right(440, y, money + price); right(545, y, money + amount);
  }
  y -= 12; line(y); y -= 18;
  right(440, y, "PO TOTAL :", 11, true); right(545, y, money + po.total, 11, true);
  y -= 40; text(45, y, "Authorised Signatory: ______________");

  const content = ops.join("\n");
  const objs = [
    "<< /Type /Catalog /Pages 2 0 R >>",
    "<< /Type /Pages /Kids [3 0 R] /Count 1 >>",
    "<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595.28 841.89] /Resources << /Font << /F1 4 0 R /F2 5 0 R >> >> /Contents 6 0 R >>",
    "<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica /Encoding /WinAnsiEncoding >>",
    "<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold /Encoding /WinAnsiEncoding >>",
    `<< /Length ${Buffer.byteLength(content)} >>\nstream\n${content}\nendstream`,
  ];
  let pdf = "%PDF-1.4\n";
  const offsets = [];
  objs.forEach((o, i) => { offsets.push(Buffer.byteLength(pdf)); pdf += `${i + 1} 0 obj\n${o}\nendobj\n`; });
  const xref = Buffer.byteLength(pdf);
  pdf += `xref\n0 ${objs.length + 1}\n0000000000 65535 f \n` + offsets.map((o) => String(o).padStart(10, "0") + " 00000 n \n").join("");
  pdf += `trailer\n<< /Size ${objs.length + 1} /Root 1 0 R >>\nstartxref\n${xref}\n%%EOF\n`;
  fs.writeFileSync(path.join(OUT, file), pdf, "latin1");
}

fs.mkdirSync(OUT, { recursive: true });
