2	// The UI only decides what to SHOW; every rule is enforced again by the server.
3	
4	async function api(path, options = {}) {
5	  const opts = { credentials: "same-origin", ...options };
6	  if (opts.json !== undefined) {
7	    opts.method = opts.method || "POST";
8	    opts.headers = { "Content-Type": "application/json", ...(opts.headers || {}) };
9	    opts.body = JSON.stringify(opts.json);
10	    delete opts.json;
11	  }
12	  let res;
13	  try {
14	    res = await fetch(path, opts);
15	  } catch (e) {
16	    throw { status: 0, error: "Can't reach the server. Check your connection and try again." };
17	  }
18	  let body = {};
19	  try { body = await res.json(); } catch (e) { /* non-JSON reply */ }
20	  if (res.status === 401 && !path.startsWith("/api/login")) {
21	    window.location.href = "/login";
22	    throw { status: 401, error: "Please log in." };
23	  }
24	  if (!res.ok) {
25	    const msg = body.error || `Request failed (${res.status}).`;
26	    throw { ...body, status: res.status, error: body.request_id && res.status >= 500 ? `${msg} (ref ${body.request_id})` : msg };
27	  }
28	  return body;
29	}
