.field-error { border-color: var(--bad) !important; background: #fff0f0 !important; }
.err-text { color: var(--bad); font-size: 13px; margin-top: 3px; }
table { width: 100%; border-collapse: collapse; }
th, td { text-align: left; padding: 7px 8px; border-bottom: 1px solid var(--line); vertical-align: top; }
th { font-size: 13px; color: var(--muted); font-weight: 600; }
td.num, th.num { text-align: right; }
tr.clickable { cursor: pointer; } tr.clickable:hover { background: var(--bg); }
.items input { min-width: 70px; }
.items td:nth-child(3) { width: 34%; } .items td:nth-child(2) { width: 13%; }
.badge { font-size: 12px; font-weight: 600; padding: 2px 8px; border-radius: 10px; border: 1px solid; }
.badge-draft { color: var(--muted); } .badge-submitted { color: var(--info); }
.badge-approved { color: var(--ok); } .badge-rejected { color: var(--bad); }
.alert { padding: 10px 14px; border-radius: 6px; margin-bottom: 12px; border: 1px solid; }
.alert-error { color: var(--bad); background: #fff0f0; } .alert-ok { color: var(--ok); background: #effff3; }
.alert-warn { color: var(--warn); background: #fff8e1; } .alert-info { color: var(--info); background: #eef6ff; }
.tabs { display: flex; gap: 6px; margin-bottom: 12px; }
.tabs button.active { background: var(--ink); color: #fff; border-color: var(--ink); }
.actions { display: flex; flex-wrap: wrap; gap: 10px; align-items: center; }
.history li { margin-bottom: 8px; }
.muted { color: var(--muted); } .small { font-size: 13px; }
.login-box { max-width: 380px; margin: 80px auto; }
.checks li.pass { color: var(--ok); } .checks li.fail { color: var(--bad); } .checks li.note { color: var(--warn); }

