/* PO Approvals: one stylesheet for all three pages. Plain CSS, no framework. */
:root {
  --ink: #1c1917; --muted: #6b645e; --line: #e7e1da; --bg: #f7f4f0; --card: #fff;
  --brand: #6b3e26; --brand-dark: #4e2c1a; --brand-soft: #f3ebe4; --brand-ink: #fff;
  --ok: #157347; --ok-soft: #e8f5ee; --bad: #c62828; --bad-soft: #fdecec;
  --warn: #8a5a00; --warn-soft: #fff6df; --info: #1d5fbf; --info-soft: #eaf2fd;
  --radius: 12px; --shadow: 0 1px 2px rgba(28, 25, 23, .05), 0 4px 14px rgba(28, 25, 23, .05);
}
* { box-sizing: border-box; }
[hidden] { display: none !important; }  /* .actions{display:flex} must not override hidden */

body {
  margin: 0; min-height: 100vh; color: var(--ink); background: var(--bg);
  font: 15px/1.55 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;
}
a { color: var(--brand); }
a:hover { color: var(--brand-dark); }

/* ---- top bar ---- */
header.top {
  position: sticky; top: 0; z-index: 10;
  display: flex; align-items: center; justify-content: space-between; gap: 12px;
  padding: 12px 28px; color: var(--brand-ink);
  background: linear-gradient(90deg, var(--brand-dark), var(--brand));
  box-shadow: 0 2px 10px rgba(78, 44, 26, .25);
}
header.top > a { color: inherit; text-decoration: none; font-weight: 700; font-size: 16px; letter-spacing: .2px; }
header.top > a::before {
  content: "PO"; display: inline-grid; place-items: center; width: 28px; height: 28px; margin-right: 10px;
  border-radius: 8px; background: rgba(255, 255, 255, .18); font-size: 11px; font-weight: 800; vertical-align: middle;
}
header.top small { opacity: .8; }
#userbar { display: flex; gap: 14px; align-items: center; font-size: 14px; }
#userbar > span { background: rgba(255, 255, 255, .14); padding: 4px 12px; border-radius: 999px; }
#userbar button.link { color: #fff; opacity: .9; }
#userbar button.link:hover { opacity: 1; }

/* ---- layout ---- */
main { max-width: 1100px; margin: 28px auto 48px; padding: 0 16px; }
.card {
  background: var(--card); border: 1px solid var(--line); border-radius: var(--radius);
  padding: 20px 24px; margin-bottom: 18px; box-shadow: var(--shadow); overflow-x: auto;
}
h1 { font-size: 24px; margin: 0 0 6px; letter-spacing: -.2px; }
h2 { font-size: 15px; margin: 0 0 14px; text-transform: uppercase; letter-spacing: .6px; color: var(--muted); }
.muted { color: var(--muted); } .small { font-size: 13px; }

/* ---- buttons ---- */
button, .button {
  font: inherit; font-weight: 600; font-size: 14px; padding: 8px 16px; border-radius: 8px;
  border: 1px solid var(--line); background: #fff; color: var(--ink); cursor: pointer;
  text-decoration: none; display: inline-block; transition: background .15s, box-shadow .15s, transform .05s;
}
button:hover { background: var(--brand-soft); }
button:active { transform: translateY(1px); }
button:focus-visible, input:focus-visible, textarea:focus-visible { outline: 3px solid rgba(107, 62, 38, .25); outline-offset: 1px; }
button.primary { background: var(--brand); color: #fff; border-color: var(--brand); }
button.primary:hover { background: var(--brand-dark); }
button.approve { background: var(--ok); color: #fff; border-color: var(--ok); }
button.approve:hover { background: #0f5a37; }
button.reject { background: #fff; color: var(--bad); border-color: var(--bad); }
button.reject:hover { background: var(--bad-soft); }
button.link { background: none; border: none; color: inherit; text-decoration: underline; padding: 0; font-weight: 500; }
button:disabled, button:disabled:hover { opacity: .55; cursor: not-allowed; transform: none; }

/* ---- forms ---- */
input, textarea {
  font: inherit; padding: 9px 11px; border: 1px solid var(--line); border-radius: 8px;
  width: 100%; background: #fff; transition: border-color .15s, box-shadow .15s;
}
input:focus, textarea:focus { border-color: var(--brand); box-shadow: 0 0 0 3px rgba(107, 62, 38, .12); outline: none; }
input[readonly], textarea[readonly] { background: #faf8f6; color: #3d3833; }
input[type="file"] { padding: 6px; background: var(--brand-soft); border-style: dashed; }
input[type="file"]::file-selector-button {
  font: inherit; font-weight: 600; margin-right: 12px; padding: 6px 12px; border: 0; border-radius: 6px;
  background: #fff; color: var(--brand); cursor: pointer;
}
label { display: block; font-size: 13px; font-weight: 600; color: var(--muted); margin-bottom: 5px; }
.grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 16px; }
.field-error { border-color: var(--bad) !important; background: var(--bad-soft) !important; }
.err-text { color: var(--bad); font-size: 13px; margin-top: 4px; }

/* ---- tables ---- */
table { width: 100%; border-collapse: collapse; }
th, td { text-align: left; padding: 10px 10px; border-bottom: 1px solid var(--line); vertical-align: middle; }
th {
  font-size: 12px; color: var(--muted); font-weight: 700; text-transform: uppercase; letter-spacing: .5px;
  background: #faf8f6;
}
thead tr:first-child th:first-child { border-top-left-radius: 8px; }
thead tr:first-child th:last-child { border-top-right-radius: 8px; }
tbody tr:last-child td { border-bottom: 0; }
td.num, th.num { text-align: right; font-variant-numeric: tabular-nums; }
tr.clickable { cursor: pointer; transition: background .12s; }
tr.clickable:hover { background: var(--brand-soft); }
tr.clickable td:first-child { font-weight: 600; color: var(--brand); }
.items td { padding: 6px 6px; }
.items input { min-width: 70px; }
.items td:nth-child(3) { width: 34%; } .items td:nth-child(2) { width: 13%; }
.items td:first-child { color: var(--muted); font-size: 13px; }

/* ---- status badges ---- */
.badge {
  display: inline-block; font-size: 11px; font-weight: 700; letter-spacing: .5px;
  padding: 3px 10px; border-radius: 999px; border: 1px solid transparent;
}
.badge-draft { color: var(--muted); background: #f1eeea; border-color: #e2dcd5; }
.badge-submitted { color: var(--info); background: var(--info-soft); border-color: #c9dcf7; }
.badge-approved { color: var(--ok); background: var(--ok-soft); border-color: #bfe3cf; }
.badge-rejected { color: var(--bad); background: var(--bad-soft); border-color: #f5c6c6; }
#status .badge { font-size: 13px; padding: 5px 14px; }

/* ---- alerts ---- */
.alert { padding: 11px 16px; border-radius: 10px; margin-bottom: 12px; border: 1px solid; border-left-width: 4px; }
.alert-error { color: var(--bad); background: var(--bad-soft); border-color: #f5c6c6; border-left-color: var(--bad); }
.alert-ok { color: var(--ok); background: var(--ok-soft); border-color: #bfe3cf; border-left-color: var(--ok); }
.alert-warn { color: var(--warn); background: var(--warn-soft); border-color: #f2dfa8; border-left-color: #c98f00; }
.alert-info { color: var(--info); background: var(--info-soft); border-color: #c9dcf7; border-left-color: var(--info); }

/* ---- tabs (list page) ---- */
.tabs { display: inline-flex; gap: 4px; margin-bottom: 16px; padding: 4px; background: #f1eeea; border-radius: 10px; }
.tabs button { border: 0; background: transparent; color: var(--muted); }
.tabs button:hover { background: rgba(255, 255, 255, .7); color: var(--ink); }
.tabs button.active { background: #fff; color: var(--ink); box-shadow: 0 1px 3px rgba(0, 0, 0, .1); }

.actions { display: flex; flex-wrap: wrap; gap: 10px; align-items: center; }

/* ---- checks list ---- */
.checks { list-style: none; padding: 0; margin: 0; display: grid; gap: 6px; }
.checks li { padding: 8px 12px; border-radius: 8px; font-size: 14px; }
.checks li.pass { color: var(--ok); background: var(--ok-soft); }
.checks li.fail { color: var(--bad); background: var(--bad-soft); }
.checks li.note { color: var(--warn); background: var(--warn-soft); }

/* ---- history timeline ---- */
.history { list-style: none; padding: 0 0 0 22px; margin: 0; position: relative; }
.history::before { content: ""; position: absolute; left: 6px; top: 6px; bottom: 6px; width: 2px; background: var(--line); }
.history li { position: relative; margin-bottom: 14px; }
.history li:last-child { margin-bottom: 0; }
.history li::before {
  content: ""; position: absolute; left: -21px; top: 6px; width: 12px; height: 12px; border-radius: 50%;
  background: #fff; border: 3px solid var(--brand);
}
.history li.muted::before { border-color: var(--line); }
.history li .small { margin-top: 2px; padding: 6px 10px; background: #faf8f6; border-radius: 6px; display: inline-block; }

/* ---- login page ---- */
.login-box { max-width: 400px; margin: 72px auto; padding: 32px 32px 28px; }
.login-box h1 { margin-bottom: 18px; }
.login-box p { margin: 0 0 16px; }
.login-box button.primary { width: 100%; padding: 11px; font-size: 15px; }

@media (max-width: 640px) {
  header.top { padding: 10px 16px; }
  main { margin-top: 18px; }
  .card { padding: 16px; }
  #userbar small { display: none; }
}

