    { sku: "CT-022", description: "Mono Carton Face Scrub", quantity: "2000", unit_price: "4.50", line_total: "9,000.00" },
  ];
  const hist = [
    { action: "SUBMIT", by: "creator1", at: "2026-11-27T16:16:50+00:00", from_status: "DRAFT", to_status: "SUBMITTED", remark: null },
