    extraction_method: "text_layer", has_pdf: true, pdf_filename: "demo_3_cartons_mismatch.pdf", line_items: lines,
  };
  const failChecks = { ok: false, errors: { total: "Line items add up to ₹26,600.00, but the PO total says ₹28,600.00." }, line_errors: {}, line_items_checked: true, totals_match: false, calculated_total_paise: 2660000 };
  const okChecks = { ok: true, errors: {}, line_errors: {}, line_items_checked: true, totals_match: true, calculated_total_paise: 2660000 };
  const pos = {
    draft: { ...base, status: "DRAFT", total: "28,600.00", total_paise: 2860000, is_own: true, checks: failChecks, history: [],
      permissions: { can_edit: true, can_submit: true, can_discard: true, can_decide: false } },
    submitted: { ...base, status: "SUBMITTED", total: "26,600.00", total_paise: 2660000, is_own: false, checks: okChecks, history: hist.slice(0, 1),
      permissions: { can_edit: false, can_submit: false, can_discard: false, can_decide: true } },
    rejected: { ...base, status: "REJECTED", total: "26,600.00", total_paise: 2660000, is_own: true, checks: okChecks, history: hist.slice(0, 2),
      permissions: { can_edit: true, can_submit: true, can_discard: false, can_decide: false } },
    approved: { ...base, status: "APPROVED", total: "26,600.00", total_paise: 2660000, is_own: true, checks: okChecks, history: hist,
      permissions: { can_edit: false, can_submit: false, can_discard: false, can_decide: false } },
  };
  window.fetch = async (url) => {
    const u = String(url);
    let body = {};
    if (u.startsWith("/api/me")) body = { user: me };
    else if (u.startsWith("/api/pos?view=")) body = { items: lists[u.split("=")[1]] || [] };
    else if (u.startsWith("/api/pos/")) body = { po: pos[variant] };
    await new Promise((r) => setTimeout(r, 150));
    return { ok: true, status: 200, json: async () => body };
  };
})();

